contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint filler) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(filler < 10);
        require(c.balances(address(this)) == 0);
        uint ethBefore = address(c).balance;
        uint myEthBefore = address(this).balance;
        c.withdraw(); if (__ESBMC_reverted()) return;
        uint ethAfterFirst = address(c).balance;
        uint myEthAfterFirst = address(this).balance;
        c.withdraw(); if (__ESBMC_reverted()) return;
        uint ethAfterSecond = address(c).balance;
        uint myEthAfterSecond = address(this).balance;
        assert(
            ethAfterFirst == ethBefore &&
            myEthAfterFirst == myEthBefore &&
            ethAfterSecond == ethBefore &&
            myEthAfterSecond == myEthBefore &&
            c.balances(address(this)) == 0
        );
    }
    receive() external payable {}
}

