// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 filler) internal {
        vm.deal(address(c), VALUE_CAP);
        filler = bound(filler, 0, 9);
        vm.assume(c.balances(address(this)) == 0);
        uint ethBefore = address(c).balance;
        uint myEthBefore = address(this).balance;
        try c.withdraw() {} catch { return; }
        uint ethAfterFirst = address(c).balance;
        uint myEthAfterFirst = address(this).balance;
        try c.withdraw() {} catch { return; }
        uint ethAfterSecond = address(c).balance;
        uint myEthAfterSecond = address(this).balance;
        assertTrue(ethAfterFirst == ethBefore &&
            myEthAfterFirst == myEthBefore &&
            ethAfterSecond == ethBefore &&
            myEthAfterSecond == myEthBefore &&
            c.balances(address(this)) == 0);
    }

    function testFuzz_run(uint256 filler) public {
        _run(filler);
    }

    receive() external payable {}
}
